def read_latest_telemetry():
    if not os.path.exists(TELEMETRY_LOG):
        return []
    active_jobs = {}
    try:
        with open(TELEMETRY_LOG, "r") as f:
            for line in f:
                if not line.strip():
                    continue
                entry = json.loads(line)
                target = entry.get("target") or "System"
                active_jobs[target] = entry
    except Exception:
        pass
    return list(active_jobs.values())

